import pandas as pd
from statsmodels.regression.linear_model import OLS
from statsmodels.stats.outliers_influence import variance_inflation_factor
import numpy as np

# Load the data
df = pd.read_csv('flow.csv')

# Define the variables
x = df['p44/42']
y = df['praf']

# Check for missing values
if x.isnull().any() or y.isnull().any():
    print('Missing values detected. Causal relationship is uncertain.')
else:
    # Perform linear regression
    try:
        ols_model = OLS(y, x).fit()
    except np.linalg.LinAlgError:
        print('Multicollinearity detected. Causal relationship is uncertain.')
    else:
        # Calculate the VIF
        vif = variance_inflation_factor(np.array([x]).T, 0)

        # Check for multicollinearity
        if vif > 5:
            print('Multicollinearity detected. Causal relationship is uncertain.')
        else:
            # Check the p-value of the coefficient
            if ols_model.pvalues[0] < 0.05:
                print('B. praf causes p44/42')
            else:
                print('A. p44/42 causes praf')

